import React from 'react'
import * as Icons from '../icons'
import type SvgIcon from '../SvgIcon/SvgIcon'
import { AriaLiveRole } from '../utilities/aria'
import type { AlertProps } from './Alert'
import AlertComponent from './Alert'

const roles: Record<
  string,
  AriaLiveRole.Alert | AriaLiveRole.Status | undefined
> = {
  None: undefined,
  'AriaLiveRole.Alert': AriaLiveRole.Alert,
  'AriaLiveRole.Status': AriaLiveRole.Status,
}

export default {
  title: 'Components/Alert',
  component: AlertComponent,
  argTypes: {
    actionLabels: {
      control: { type: 'object' },
      description:
        'NOTE: not a prop. Array of strings representing the labels for action buttons within `<Alert.Actions>`',
      table: {
        category: 'Content',
      },
    },
    description: {
      description:
        'NOTE: not a prop. The main descriptive text content of the alert set via `<Alert.Description>`',
      table: {
        category: 'Content',
      },
    },
    icon: {
      control: { type: 'select' },
      options: ['None', ...Object.keys(Icons)],
      mapping: { None: undefined, ...Icons },
      table: {
        category: 'Appearance',
      },
    },
    role: {
      control: { options: Object.keys(roles), type: 'select' },
      options: [...Object.keys(roles)],
      mapping: roles,
      table: {
        category: 'Accessibility',
      },
    },
    severity: {
      table: {
        category: 'State',
      },
    },
    title: {
      description:
        'NOTE: not a prop. The title of the alert set via `<Alert.Title>`',
      table: {
        category: 'Content',
      },
    },
    variant: {
      table: {
        category: 'Appearance',
      },
    },
  },
  args: {
    actionLabels: ['Primary Action', 'Secondary Action'],
    description: 'This is a Description',
    icon: 'None',
    role: AriaLiveRole.Alert,
    severity: 'success',
    title: '',
    variant: 'filled',
  },
}

function Template(
  args: AlertProps & {
    actionLabels: string[]
    description: string
    icon?: typeof SvgIcon
    role: string
    title: string
  },
): JSX.Element {
  const Icon = args.icon

  return (
    <AlertComponent
      icon={Icon ? <Icon /> : null}
      role={args.role}
      severity={args.severity}
      variant={args.variant}
    >
      <AlertComponent.Content>
        {args.title ? (
          <AlertComponent.Title>{args.title}</AlertComponent.Title>
        ) : null}
        <AlertComponent.Description>
          {args.description}
        </AlertComponent.Description>
      </AlertComponent.Content>
      {args.actionLabels.length ? (
        <AlertComponent.Actions>
          {args.actionLabels.map((label) => (
            <AlertComponent.Button key={label}>{label}</AlertComponent.Button>
          ))}
        </AlertComponent.Actions>
      ) : null}
    </AlertComponent>
  )
}

export const Default = {
  render: Template,
}

